#=
    Module comprising of functions which compute independent residuals of the BDNK equations of motion. The BDNK system we solve consists of
    two wave equations for the energy density and velocity perturbations (δε, δu) and a constraint equation for the
    metric perturbation δλ. We solve this system with a Crank-Nicholson time discretization which couples time levels (n, n+1) by discretizing the equations at the half
    time step n + 1/2 (t + Δt / 2) and then using a leapfrog stencil for time derivatives and averaging functions u[n+1/2,r] = (u[n+1,r] + u[n,r]) / 2. The independent
    residuals below discretize the equations in a distinct way, using a leapfrog scheme which couples time levels (n-1, n, n+1). Note that we monitor two sets of IRs: two for the constrained system
    (we don't have three because when we cast the BDNK system in first-order form, the constraint equation contains no time derivatives), and three for the original "wave-like" system. The
    latter system is how the Einstein-BDNK system naturally falls out of the EFEs and conservation of energy-momentum, but we find that solving the constrained system is
    more numerically stable. We additionally check that the independent residual of the wave-like system converges in the continuum limit to ensure that we are solving the original equations
    before formulating them in the form of a constrained system.
=#

module BDNKIndependentResidual

# two wave equations for δu and δε in the constrained system discretized in time using a leapfrog scheme which couples time levels (n-1, n, n+1)
module ConstrainedSystem

module Center

Eq1(v2np1::Vector{Float64}, v2nm1::Vector{Float64}, u1n::Vector{Float64}, u2n::Vector{Float64}, u3n::Vector{Float64}, v1n::Vector{Float64}, v2n::Vector{Float64}, CNSystem, h::Float64, k::Float64)::Float64 = (CNSystem.E1*(-3*u1n[1] + 4*u1n[2] - u1n[3]))/(2.0*h) + CNSystem.E2*u2n[1] + (CNSystem.E3*(2*u2n[1] - 5*u2n[2] + 4*u2n[3] - u2n[4]))/(2.0*h^2) + (CNSystem.E4*(-3*v1n[1] + 4*v1n[2] - v1n[3]))/(2.0*h) + CNSystem.E5*v2n[1] + (CNSystem.E6*(-v2nm1[1] + v2np1[1]))/(2.0*k)

end

module Interior

Eq1(v1np1::Vector{Float64}, v2np1::Vector{Float64}, v1nm1::Vector{Float64}, v2nm1::Vector{Float64}, u1n::Vector{Float64}, u2n::Vector{Float64}, u3n::Vector{Float64}, v1n::Vector{Float64}, v2n::Vector{Float64}, CNSystem, j::Int64, h::Float64, k::Float64)::Float64 = CNSystem.A1[j]*u1n[j] + (CNSystem.A2[j]*(-u1n[j-1] + u1n[j+1]))/(2.0*h) + (CNSystem.A3[j]*(u1n[j-1] - 2*u1n[j] + u1n[j+1]))/h^2 + CNSystem.A7[j]*u2n[j] + (CNSystem.A8[j]*(-u2n[j-1] + u2n[j+1]))/(2.0*h) + (CNSystem.A9[j]*(u2n[j-1] - 2*u2n[j] + u2n[j+1]))/h^2 + CNSystem.A13[j]*u3n[j] + (CNSystem.A14[j]*(-u3n[j-1] + u3n[j+1]))/(2.0*h) + CNSystem.A4[j]*v1n[j] + (CNSystem.A5[j]*(-v1n[j-1] + v1n[j+1]))/(2.0*h) + (CNSystem.A6[j]*(-v1nm1[j] + v1np1[j]))/(2.0*k) + CNSystem.A10[j]*v2n[j] + (CNSystem.A11[j]*(-v2n[j-1] + v2n[j+1]))/(2.0*h) + (CNSystem.A12[j]*(-v2nm1[j] + v2np1[j]))/(2.0*k)


Eq2(v1np1::Vector{Float64}, v2np1::Vector{Float64}, v1nm1::Vector{Float64}, v2nm1::Vector{Float64}, u1n::Vector{Float64}, u2n::Vector{Float64}, u3n::Vector{Float64}, v1n::Vector{Float64}, v2n::Vector{Float64}, CNSystem, j::Int64, h::Float64, k::Float64)::Float64 = CNSystem.B1[j]*u1n[j] + (CNSystem.B2[j]*(-u1n[j-1] + u1n[j+1]))/(2.0*h) + (CNSystem.B3[j]*(u1n[j-1] - 2*u1n[j] + u1n[j+1]))/h^2 + CNSystem.B7[j]*u2n[j] + (CNSystem.B8[j]*(-u2n[j-1] + u2n[j+1]))/(2.0*h) + (CNSystem.B9[j]*(u2n[j-1] - 2*u2n[j] + u2n[j+1]))/h^2 + CNSystem.B13[j]*u3n[j] + (CNSystem.B14[j]*(-u3n[j-1] + u3n[j+1]))/(2.0*h) + CNSystem.B4[j]*v1n[j] + (CNSystem.B5[j]*(-v1n[j-1] + v1n[j+1]))/(2.0*h) + (CNSystem.B6[j]*(-v1nm1[j] + v1np1[j]))/(2.0*k) + CNSystem.B10[j]*v2n[j] + (CNSystem.B11[j]*(-v2n[j-1] + v2n[j+1]))/(2.0*h) + (CNSystem.B12[j]*(-v2nm1[j] + v2np1[j]))/(2.0*k)


end

module Surface

Eq1(v1np1::Vector{Float64}, v2np1::Vector{Float64}, v1nm1::Vector{Float64}, v2nm1::Vector{Float64}, u1n::Vector{Float64}, u2n::Vector{Float64}, u3n::Vector{Float64}, v1n::Vector{Float64}, v2n::Vector{Float64}, CNSystem, j::Int64, h::Float64, k::Float64)::Float64 = CNSystem.A1[j]*u1n[j] + (CNSystem.A3[j]*(-u1n[j-3] + 4*u1n[j-2] - 5*u1n[j-1] + 2*u1n[j]))/h^2 + (CNSystem.A2[j]*(u1n[j-2] - 4*u1n[j-1] + 3*u1n[j]))/(2.0*h) + CNSystem.A7[j]*u2n[j] + (CNSystem.A9[j]*(-u2n[j-3] + 4*u2n[j-2] - 5*u2n[j-1] + 2*u2n[j]))/h^2 + (CNSystem.A8[j]*(u2n[j-2] - 4*u2n[j-1] + 3*u2n[j]))/(2.0*h) + CNSystem.A13[j]*u3n[j] + (CNSystem.A14[j]*(u3n[j-2] - 4*u3n[j-1] + 3*u3n[j]))/(2.0*h) + CNSystem.A4[j]*v1n[j] + (CNSystem.A5[j]*(v1n[j-2] - 4*v1n[j-1] + 3*v1n[j]))/(2.0*h) + (CNSystem.A6[j]*(-v1nm1[j] + v1np1[j]))/(2.0*k) + CNSystem.A10[j]*v2n[j] + (CNSystem.A11[j]*(v2n[j-2] - 4*v2n[j-1] + 3*v2n[j]))/(2.0*h) + (CNSystem.A12[j]*(-v2nm1[j] + v2np1[j]))/(2.0*k)


Eq2(v1np1::Vector{Float64}, v2np1::Vector{Float64}, v1nm1::Vector{Float64}, v2nm1::Vector{Float64}, u1n::Vector{Float64}, u2n::Vector{Float64}, u3n::Vector{Float64}, v1n::Vector{Float64}, v2n::Vector{Float64}, CNSystem, j::Int64, h::Float64, k::Float64)::Float64 = CNSystem.B1[j]*u1n[j] + (CNSystem.B3[j]*(-u1n[j-3] + 4*u1n[j-2] - 5*u1n[j-1] + 2*u1n[j]))/h^2 + (CNSystem.B2[j]*(u1n[j-2] - 4*u1n[j-1] + 3*u1n[j]))/(2.0*h) + CNSystem.B7[j]*u2n[j] + (CNSystem.B9[j]*(-u2n[j-3] + 4*u2n[j-2] - 5*u2n[j-1] + 2*u2n[j]))/h^2 + (CNSystem.B8[j]*(u2n[j-2] - 4*u2n[j-1] + 3*u2n[j]))/(2.0*h) + CNSystem.B13[j]*u3n[j] + (CNSystem.B14[j]*(u3n[j-2] - 4*u3n[j-1] + 3*u3n[j]))/(2.0*h) + CNSystem.B4[j]*v1n[j] + (CNSystem.B5[j]*(v1n[j-2] - 4*v1n[j-1] + 3*v1n[j]))/(2.0*h) + (CNSystem.B6[j]*(-v1nm1[j] + v1np1[j]))/(2.0*k) + CNSystem.B10[j]*v2n[j] + (CNSystem.B11[j]*(v2n[j-2] - 4*v2n[j-1] + 3*v2n[j]))/(2.0*h) + (CNSystem.B12[j]*(-v2nm1[j] + v2np1[j]))/(2.0*k)


end

end

# two genuine wave equations for δu and δε and non-genuine wave equation for δλ in the system directly obtained from the Einstein and conservation of energy-momentym. Discretized in time using a leapfrog scheme which couples time levels (n-1, n, n+1)
module WaveSystem

module Interior

Eq1(i::Int64, v1_tm1::Vector{Float64}, v2_tm1::Vector{Float64}, v3_tm1::Vector{Float64}, u1::Vector{Float64}, u2::Vector{Float64}, u3::Vector{Float64}, w1::Vector{Float64}, w2::Vector{Float64}, w3::Vector{Float64}, v1::Vector{Float64}, v2::Vector{Float64}, v3::Vector{Float64}, v1_tp1::Vector{Float64}, v2_tp1::Vector{Float64}, v3_tp1::Vector{Float64}, m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64, h::Float64, k::Float64)::Float64 = (256*exp(ν/2.)*L*π^3*r^7*(3*ζ + 4*η)*p^3*τP*u1[i]*cs^2 + 3*exp(ν)*(r - 2*m)*u3[i]*(2*m + 8*π*r^2*(r - 2*m)*ε)*cs^4 + 32*exp(ν/2.)*π^2*r^4*p^2*(6*exp(ν/2.)*r*(r - 2*m)*u3[i]*cs^4 - L*r*(r - 2*m)*(3*ζ + 4*η)*τP*(v3[i] + 4*w1[i])*cs^4 + 2*L*(3*ζ + 4*η)*u1[i]*cs^2*(4*π*r^3*(p + ε)*cs^2 + 2*m*τP*(1 + 5*cs^2) + τP*(-3*r*cs^2 + 4*π*r^3*ε*(1 - 4*cs^2)))) + (r - 2*m)*cs^4*((-3*r^2*(r - 2*m)*(-v3_tm1[i] + v3_tp1[i]))/k + 3*exp(ν)*r*(r - 2*m)*w3[i] - 3*exp(ν)*(r - 2*m)^2*w3[i] + (8*exp(ν/2.)*L*π*r^3*(r - 2*m)*(3*ζ + 4*η)*τP*(-v2[i-1] + v2[i+1])*cs^2)/h + 48*exp(ν)*π*r^3*(r - 2*m)*w2[i]*cs^2 + 32*exp(ν/2.)*L*π^2*r^5*(3*ζ + 4*η)*τP*(v3[i] + 4*w1[i])*ε^2*cs^2 + 24*exp(ν/2.)*L*π*r^2*ζ*((-4*r + 10*m)*w1[i] - r*(r - 2*m)*((-v3[i-1] + v3[i+1])/(2.0*h) + (-w1[i-1] + w1[i+1])/h))*(p + ε)*cs^2 - 32*exp(ν/2.)*L*π*r^2*η*(3*(r - 2*m)*v3[i] + 2*(2*r - 5*m)*w1[i] + r*(r - 2*m)*((-v3[i-1] + v3[i+1])/(2.0*h) + (-w1[i-1] + w1[i+1])/h))*(p + ε)*cs^2 + 32*exp(ν/2.)*L*π*r^3*(r - 2*m)*(3*ζ + 4*η)*τP*v2[i]*cs*cs_prime + 24*exp(ν)*π*r^2*u2[i]*cs*(2*(m + 4*π*r^3*ε)*cs + 4*r*(r - 2*m)*cs_prime) - 4*exp(ν/2.)*π*r^2*ε*(L*(3*ζ + 4*η)*τP*(2*m*v3[i] - (16*π*r^3*v2[i] + 2*r^2*((-v3[i-1] + v3[i+1])/(2.0*h) + (-w1[i-1] + w1[i+1])/h) - 2*m*(v3[i] + (r*(-v3[i-1] + v3[i+1]))/h + (2*r*(-w1[i-1] + w1[i+1]))/h))*cs^2 + 8*w1[i]*(m - r*cs^2 + 3*m*cs^2)) + 4*L*r*cs*(6*π*r^2*ζ*(v3[i] + 4*w1[i])*(p + ε)*cs + 8*π*r^2*η*(v3[i] + 4*w1[i])*(p + ε)*cs - (r - 2*m)*(3*ζ + 4*η)*τP*(v3[i] + 2*w1[i])*cs_prime)) - 12*exp(ν/2.)*L*π*r^2*ζ*v3[i]*(p + ε)*(4*r^2*(-2*π*r*p*(1 + cs^2) + cs*cs_prime) - 2*m*(1 + cs^2 + 4*r*cs*cs_prime)) - 16*exp(ν/2.)*L*π*r^2*η*v3[i]*(p + ε)*(4*r^2*(-2*π*r*p*(1 + cs^2) + cs*cs_prime) - 2*m*(1 + cs^2 + 4*r*cs*cs_prime)) - 24*exp(ν/2.)*L*π*r^2*ζ*w1[i]*(p + ε)*(4*r^2*(-2*π*r*p*(1 + cs^2) + cs*cs_prime) - 2*m*(1 + cs^2 + 4*r*cs*cs_prime)) - 32*exp(ν/2.)*L*π*r^2*η*w1[i]*(p + ε)*(4*r^2*(-2*π*r*p*(1 + cs^2) + cs*cs_prime) - 2*m*(1 + cs^2 + 4*r*cs*cs_prime))) + 4*exp(ν/2.)*π*r*p*(r*(r - 2*m)*cs^4*(12*exp(ν/2.)*r*u3[i] - L*r*(3*ζ + 4*η)*τP*v3[i] + L*(r - 2*m)*(3*ζ + 4*η)*τP*v3[i] - 4*L*r*(3*ζ + 4*η)*τP*w1[i] + 4*L*(r - 2*m)*(3*ζ + 4*η)*τP*w1[i] + 6*exp(ν/2.)*r*(r - 2*m)*w3[i] - 8*L*π*r^3*(3*ζ + 4*η)*τP*v3[i]*ε - 32*L*π*r^3*(3*ζ + 4*η)*τP*w1[i]*ε + 96*exp(ν/2.)*π*r^3*u2[i]*cs^2 + 16*L*π*r^3*(3*ζ + 4*η)*τP*v2[i]*cs^2 - L*r*(3*ζ + 4*η)*τP*v3[i]*cs^2 + L*(r - 2*m)*(3*ζ + 4*η)*τP*v3[i]*cs^2 + (L*r*(r - 2*m)*(3*ζ + 4*η)*τP*(-v3[i-1] + v3[i+1])*cs^2)/h - 4*L*r*(3*ζ + 4*η)*τP*w1[i]*cs^2 + 12*L*(r - 2*m)*(3*ζ + 4*η)*τP*w1[i]*cs^2 + (2*L*r*(r - 2*m)*(3*ζ + 4*η)*τP*(-w1[i-1] + w1[i+1])*cs^2)/h + 8*L*π*r^3*(3*ζ + 4*η)*τP*v3[i]*ε*cs^2 + 32*L*π*r^3*(3*ζ + 4*η)*τP*w1[i]*ε*cs^2 - 24*L*π*r^3*ζ*v3[i]*(p + ε)*cs^2 - 32*L*π*r^3*η*v3[i]*(p + ε)*cs^2 - 48*L*π*r^3*ζ*w1[i]*(p + ε)*cs^2 - 64*L*π*r^3*η*w1[i]*(p + ε)*cs^2 + 4*L*r*(r - 2*m)*(3*ζ + 4*η)*τP*v3[i]*cs*cs_prime + 8*L*r*(r - 2*m)*(3*ζ + 4*η)*τP*w1[i]*cs*cs_prime) + 4*L*u1[i]*cs^2*(r*cs*(6*π*r^2*ζ*(p + ε)*cs*(2*m - 2*(2*r - 5*m)*cs^2 - 8*π*r^3*ε*(-1 + cs^2)) + 16*π*r^2*η*(p + ε)*cs*(m + (r - m)*cs^2 - 4*π*r^3*ε*(-1 + cs^2)) - (r - 2*m)*(3*ζ + 4*η)*τP*(2*m - 2*(2*r - 5*m)*cs^2 - 8*π*r^3*ε*(-1 + cs^2))*cs_prime) + (3*ζ + 4*η)*τP*(m^2 + 4*m^2*cs^2 - (2*r^2 - 8*r*m + 5*m^2)*cs^4 + 16*π^2*r^6*ε^2*cs^2*(-4 + 3*cs^2) + 2*r*(r - 2*m)*m*cs*cs_prime + 8*π*r^3*ε*(m - 2*(r - 2*m)*cs^2 + (r - 5*m)*cs^4 + r*(r - 2*m)*cs*cs_prime)))) + 8*exp(ν/2.)*L*π*r*u1[i]*cs^2*(96*π^2*r^6*(3*ζ + 4*η)*τP